function total(values) {
  if (!Array.isArray(values)) {
    throw new Error('Expected array');
  }
  let sum = 0;
  for (const val of values) {
    if (typeof val !== 'number' || isNaN(val) || !isFinite(val)) {
      throw new Error('All elements must be finite numbers');
    }
    sum += val;
  }
  return sum;
}

