const main = () => {
  const args = process.argv.slice(2);
  let sum = 0;
  for (const arg of args) {
    const num = parseFloat(arg);
    if (isNaN(num)) {
      process.exit(1);
    }
    sum += num;
  }
  console.log(sum);
};
export default main;
